Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <cstdio>
#include <iostream>
#include <cmath>
#include <cfloat>
using namespace std;

double abs_value(double n){
    return n >= 0 ? n : -n;
}

int find_nearest(int x, int y, int b){
    double target = (double)x / y;
    int low=0, high=1000000;
    for(int i=0; i<25; i++){
        int mid = (low + high) / 2;
        if ((double)mid / b < target)
            low = mid;
        else
            high = mid;
    }
    int best_a;
    double min_diff=DBL_MAX;
    for(int a=low-10; a<=high+10; a++){
        double diff = abs_value((double)a / b - target);
        if (diff < min_diff){
            min_diff = diff;
            best_a = a;
        }
    }
    return best_a;
}

int main(){
    int x,y,n;
    scanf("%d %d %d",&x,&y,&n);
    int optimal_a, optimal_b;
    double min_diff=DBL_MAX;
    for(int b=1; b<=n; b++){
        int a = find_nearest(x,y,b);
        double diff = abs_value((double)a/b - (double)x/y);
        if (diff < min_diff){
            min_diff = diff;
            optimal_a = a;
            optimal_b = b;
        }
    }
    printf("%d/%d\n", optimal_a, optimal_b);
    return 0;
}
